<?php
require_once __DIR__ . '/../includes/init.php'; requireAdmin(); $pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST') { verifyCsrf(); $itemId=(int)($_POST['item_id']??0);$type=(string)($_POST['movement_type']??'');$qty=filter_var($_POST['quantity']??null,FILTER_VALIDATE_INT);$date=(string)($_POST['movement_date']??'');$note=trim((string)($_POST['reference_note']??''));
 if(!$itemId||!in_array($type,['IN','OUT'],true)||$qty===false||$qty===null||$qty<1||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||!checkdate((int)substr($date,5,2),(int)substr($date,8,2),(int)substr($date,0,4))) { flash('error','Enter a valid item, movement type, positive quantity and date.');redirect('admin/movements.php'); }
 try{$pdo->beginTransaction();$s=$pdo->prepare('SELECT quantity FROM items WHERE id=? FOR UPDATE');$s->execute([$itemId]);$item=$s->fetch();if(!$item)throw new RuntimeException('The selected item no longer exists.');if($type==='OUT'&&$qty>(int)$item['quantity'])throw new RuntimeException('Insufficient stock. Available quantity: '.$item['quantity'].'.');$delta=$type==='IN'?$qty:-$qty;$u=$pdo->prepare('UPDATE items SET quantity=quantity+? WHERE id=?');$u->execute([$delta,$itemId]);$m=$pdo->prepare('INSERT INTO stock_movements(item_id,movement_type,quantity,movement_date,reference_note,created_by) VALUES(?,?,?,?,?,?)');$m->execute([$itemId,$type,$qty,$date,$note?:null,currentUser()['id']]);$pdo->commit();flash('success','Stock '.$type.' recorded successfully.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error',$e instanceof RuntimeException?$e->getMessage():'Could not save the stock movement.');}redirect('admin/movements.php'); }
$filters=['item_id'=>(string)($_GET['item_id']??''),'movement_type'=>(string)($_GET['movement_type']??''),'start_date'=>(string)($_GET['start_date']??''),'end_date'=>(string)($_GET['end_date']??'')];$rows=historyRows($filters);$items=allItems();$title='Stock Movements';$active='movements';layoutStart($title,$active);
?><div class="page-heading"><div><div class="eyebrow">INVENTORY CONTROL</div><h1>Stock movements</h1><p>Record incoming stock and outgoing orders.</p></div></div><section class="panel form-panel"><div class="panel-heading"><div><h2>Record a movement</h2><p>Stock levels update as soon as a movement is saved.</p></div><span class="panel-tag">ADMIN</span></div><form method="post" class="form-grid movement-form"><input type="hidden" name="csrf" value="<?= e(csrfToken()) ?>"><label class="span-2">Item<select name="item_id" required><option value="">Select an item</option><?php foreach($items as $i): ?><option value="<?= e($i['id']) ?>"><?= e($i['item_code'].' — '.$i['item_name'].' ('.$i['quantity'].' '.$i['unit'].')') ?></option><?php endforeach; ?></select></label><label>Movement type<select name="movement_type" required><option value="IN">Stock IN</option><option value="OUT">Stock OUT</option></select></label><label>Quantity<input type="number" name="quantity" min="1" step="1" required></label><label>Date<input type="date" name="movement_date" value="<?= e(date('Y-m-d')) ?>" required></label><label class="span-2">Reference / note<input name="reference_note" maxlength="255" placeholder="e.g. Purchase order or dispatch number"></label><div class="form-actions span-2"><button class="button primary">＋ Save movement</button></div></form></section>
<section class="panel"><div class="panel-heading"><div><h2>Stock history</h2><p><?= count($rows) ?> matching movement<?= count($rows)===1?'':'s' ?></p></div></div><form class="filter-bar wrap" method="get"><select name="item_id"><option value="">All items</option><?php foreach($items as $i): ?><option value="<?= e($i['id']) ?>" <?= (string)$i['id']===$filters['item_id']?'selected':'' ?>><?= e($i['item_code'].' · '.$i['item_name']) ?></option><?php endforeach; ?></select><select name="movement_type"><option value="">All types</option><option value="IN" <?= $filters['movement_type']==='IN'?'selected':'' ?>>IN</option><option value="OUT" <?= $filters['movement_type']==='OUT'?'selected':'' ?>>OUT</option></select><label class="date-filter">From<input type="date" name="start_date" value="<?= e($filters['start_date']) ?>"></label><label class="date-filter">To<input type="date" name="end_date" value="<?= e($filters['end_date']) ?>"></label><button class="button light">Apply filters</button><a class="text-link" href="<?= e(url('admin/movements.php')) ?>">Reset</a></form><div class="table-wrap"><table><thead><tr><th>Date</th><th>Item code</th><th>Item name</th><th>IN</th><th>OUT</th><th>Reference</th><th>User</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="7" class="empty">No stock movements match these filters.</td></tr><?php else:foreach($rows as $r):?><tr><td><?= e(dateValue($r['movement_date'])) ?></td><td><?= e($r['item_code']) ?></td><td><?= e($r['item_name']) ?></td><td class="in-text"><?= $r['movement_type']==='IN'?'+'.e($r['quantity']):'—' ?></td><td class="out-text"><?= $r['movement_type']==='OUT'?'−'.e($r['quantity']):'—' ?></td><td><?= e($r['reference_note']?:'—') ?></td><td><?= e($r['full_name']) ?></td></tr><?php endforeach;endif; ?></tbody></table></div></section><?php layoutEnd(); ?>
